{
  "name": "Lumina coworking platform",
  "overview": "A normalized relational model separates members, product plans, subscription history, spaces, shared amenities, reservations, and invoices. An associative table represents shared amenities. Financial and reservation history remain linked to anonymizable member records.",
  "tables": [
    {
      "name": "members",
      "purpose": "Member identity, optional preferred space and contact information, separable from retained financial history.",
      "columns": [
        {
          "name": "id",
          "type": "integer",
          "nullable": false,
          "description": "Application-assigned member identifier"
        },
        {
          "name": "full_name",
          "type": "string",
          "nullable": false,
          "description": "Member display name",
          "length": 120
        },
        {
          "name": "email",
          "type": "string",
          "nullable": false,
          "description": "Unique member contact address",
          "length": 254
        },
        {
          "name": "joined_on",
          "type": "date",
          "nullable": false,
          "description": "Registration date"
        },
        {
          "name": "active",
          "type": "boolean",
          "nullable": false,
          "description": "Whether the account may create bookings"
        },
        {
          "name": "preferred_space_id",
          "type": "integer",
          "nullable": true,
          "description": "Optional preferred space; preferences never imply a reservation"
        },
        {
          "name": "phone",
          "type": "string",
          "nullable": true,
          "description": "Optional member phone number in international format",
          "length": 30
        }
      ],
      "primaryKey": [
        "id"
      ],
      "unique": [
        [
          "email"
        ]
      ],
      "foreignKeys": [
        {
          "columns": [
            "preferred_space_id"
          ],
          "refTable": "spaces",
          "refColumns": [
            "id"
          ],
          "onDelete": "SET NULL"
        }
      ],
      "checks": [],
      "indexes": [],
      "functionalDependencies": [
        "id → full_name, email, joined_on, active, preferred_space_id, phone",
        "email → id, full_name, joined_on, active, preferred_space_id, phone"
      ],
      "normalization": "1NF: each column contains an atomic value. 2NF: the single-column primary key has no partial dependencies. 3NF: non-key attributes depend on a candidate key, not on another non-key attribute; related mutable facts live in their own relations.",
      "rows": [
        {
          "id": 1,
          "full_name": "Maya Bennett",
          "email": "maya.bennett@example.org",
          "joined_on": "2026-01-14",
          "active": true,
          "preferred_space_id": 1,
          "phone": "+1-202-555-0110"
        },
        {
          "id": 2,
          "full_name": "Omid Rahimi",
          "email": "omid.rahimi@example.org",
          "joined_on": "2026-02-03",
          "active": true,
          "preferred_space_id": null,
          "phone": null
        },
        {
          "id": 3,
          "full_name": "Sofia Chen",
          "email": "sofia.chen@example.org",
          "joined_on": "2026-03-21",
          "active": false,
          "preferred_space_id": 3,
          "phone": "+1-202-555-0112"
        }
      ]
    },
    {
      "name": "plans",
      "purpose": "Subscription products with stable pricing and included workspace hours.",
      "columns": [
        {
          "name": "id",
          "type": "integer",
          "nullable": false,
          "description": "Plan identifier"
        },
        {
          "name": "name",
          "type": "string",
          "nullable": false,
          "description": "Unique plan label",
          "length": 80
        },
        {
          "name": "monthly_price",
          "type": "decimal",
          "nullable": false,
          "description": "Monthly price in USD"
        },
        {
          "name": "included_hours",
          "type": "integer",
          "nullable": false,
          "description": "Included monthly booking hours"
        }
      ],
      "primaryKey": [
        "id"
      ],
      "unique": [
        [
          "name"
        ]
      ],
      "foreignKeys": [],
      "checks": [
        {
          "name": "plans_nonnegative",
          "expression": "monthly_price >= 0 AND included_hours >= 0"
        }
      ],
      "indexes": [],
      "functionalDependencies": [
        "id → name, monthly_price, included_hours",
        "name → id, monthly_price, included_hours"
      ],
      "normalization": "1NF: each column contains an atomic value. 2NF: the single-column primary key has no partial dependencies. 3NF: non-key attributes depend on a candidate key, not on another non-key attribute; related mutable facts live in their own relations.",
      "rows": [
        {
          "id": 1,
          "name": "Daylight",
          "monthly_price": 99,
          "included_hours": 10
        },
        {
          "id": 2,
