          "monthly_price": 249,
          "included_hours": 40
        },
        {
          "id": 3,
          "name": "Studio",
          "monthly_price": 499,
          "included_hours": 100
        }
      ]
    },
    {
      "name": "memberships",
      "purpose": "Effective-dated member subscriptions preserving plan enrollment history.",
      "columns": [
        {
          "name": "id",
          "type": "integer",
          "nullable": false,
          "description": "Membership identifier"
        },
        {
          "name": "member_id",
          "type": "integer",
          "nullable": false,
          "description": "Subscribed member"
        },
        {
          "name": "plan_id",
          "type": "integer",
          "nullable": false,
          "description": "Subscribed plan"
        },
        {
          "name": "starts_on",
          "type": "date",
          "nullable": false,
          "description": "First active date"
        },
        {
          "name": "ends_on",
          "type": "date",
          "nullable": true,
          "description": "Exclusive end date; null means ongoing"
        }
      ],
      "primaryKey": [
        "id"
      ],
      "unique": [
        [
          "member_id",
          "starts_on"
        ]
      ],
      "foreignKeys": [
        {
          "columns": [
            "member_id"
          ],
          "refTable": "members",
          "refColumns": [
            "id"
          ],
          "onDelete": "RESTRICT"
        },
        {
          "columns": [
            "plan_id"
          ],
          "refTable": "plans",
          "refColumns": [
            "id"
          ],
          "onDelete": "RESTRICT"
        }
      ],
      "checks": [
        {
          "name": "memberships_date_order",
          "expression": "ends_on IS NULL OR ends_on > starts_on"
        }
      ],
      "indexes": [],
      "functionalDependencies": [
        "id → member_id, plan_id, starts_on, ends_on",
        "(member_id, starts_on) → id, plan_id, ends_on"
      ],
      "normalization": "1NF: each column contains an atomic value. 2NF: the single-column primary key has no partial dependencies. 3NF: non-key attributes depend on a candidate key, not on another non-key attribute; related mutable facts live in their own relations.",
      "rows": [
