          "plan_id": 3,
          "starts_on": "2026-03-21",
          "ends_on": "2026-09-01"
        }
      ]
    },
    {
      "name": "spaces",
      "purpose": "Bookable rooms and desks, each with a location label, capacity and hourly rate.",
      "columns": [
        {
          "name": "id",
          "type": "integer",
          "nullable": false,
          "description": "Space identifier"
        },
        {
          "name": "name",
          "type": "string",
          "nullable": false,
          "description": "Name unique inside location",
          "length": 100
        },
        {
          "name": "location",
          "type": "string",
          "nullable": false,
          "description": "Location label; locations have no other attributes in this scope",
          "length": 100
        },
        {
          "name": "capacity",
          "type": "integer",
          "nullable": false,
          "description": "Maximum occupants"
        },
        {
          "name": "hourly_rate",
          "type": "decimal",
          "nullable": false,
          "description": "Booking rate in USD per hour"
        }
      ],
      "primaryKey": [
        "id"
      ],
      "unique": [
        [
          "location",
          "name"
        ]
      ],
      "foreignKeys": [],
      "checks": [
        {
          "name": "spaces_valid_capacity_rate",
          "expression": "capacity > 0 AND hourly_rate >= 0"
        }
      ],
      "indexes": [],
      "functionalDependencies": [
        "id → name, location, capacity, hourly_rate",
        "(location, name) → id, capacity, hourly_rate"
      ],
      "normalization": "1NF: each column contains an atomic value. 2NF: the single-column primary key has no partial dependencies. 3NF: non-key attributes depend on a candidate key, not on another non-key attribute; related mutable facts live in their own relations.",
      "rows": [
