            "id"
          ],
          "onDelete": "CASCADE"
        },
        {
          "columns": [
            "amenity_id"
          ],
          "refTable": "amenities",
          "refColumns": [
            "id"
          ],
          "onDelete": "CASCADE"
        }
      ],
      "checks": [],
